contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        bytes memory data = abi.encodeWithSignature("balanceOf(address)", address(this));
        uint256 beforeTestBalance = address(this).balance;
        uint256 beforeCBalance = address(c).balance;

        bool reverted;
        c.forward(address(this), data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(address(this).balance == beforeTestBalance);
    }

    receive() external payable {}
}

