pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(uint256 _data) internal {
        vm.deal(address(c), VALUE_CAP);
        bytes memory data = abi.encodeWithSignature("balanceOf(address)", address(this));
        uint256 beforeTestBalance = address(this).balance;
        uint256 beforeCBalance = address(c).balance;
        bool reverted;
        try c.forward(address(this), data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(address(this).balance == beforeTestBalance);
    }

    function testFuzz_run(uint256 _data) public {
        _run(_data);
    }

    receive() external payable {}
}
